#include <windows.h>
#include <d3d11.h>
#include <wrl/client.h>
#include "../../src/openxr/native_sharpen_client.h"
#include <atomic>
#include <cstdio>
#include <cstring>
#include <stdexcept>
#include <thread>
#include <vector>
using Microsoft::WRL::ComPtr; using edvr::openxr::NativeSharpenClient;
namespace {
using DirectSharpen=void*(__cdecl*)(void*,int,const float*,float);
unsigned checks=0;
void require(bool ok,const char* text){++checks;if(!ok)throw std::runtime_error(text);}
struct Watchdog{std::atomic<bool>done{false};std::thread t;Watchdog():t([this]{auto end=GetTickCount64()+60000;while(!done){if(GetTickCount64()>end)std::_Exit(9);Sleep(10);}}){}~Watchdog(){done=true;t.join();}};
struct Device{HMODULE module=nullptr;decltype(&D3D11CreateDevice)create=nullptr;ComPtr<ID3D11Device>dev;ComPtr<ID3D11DeviceContext>ctx;~Device(){ctx.Reset();dev.Reset();}};
Device open(const wchar_t* path){Device d;d.module=LoadLibraryExW(path,nullptr,LOAD_LIBRARY_SEARCH_DLL_LOAD_DIR|LOAD_LIBRARY_SEARCH_DEFAULT_DIRS);require(d.module,"graphics proxy loads");d.create=reinterpret_cast<decltype(d.create)>(GetProcAddress(d.module,"D3D11CreateDevice"));require(d.create,"D3D11CreateDevice export");D3D_FEATURE_LEVEL fl{};require(SUCCEEDED(d.create(nullptr,D3D_DRIVER_TYPE_WARP,nullptr,0,nullptr,0,D3D11_SDK_VERSION,&d.dev,&fl,&d.ctx))&&d.dev&&d.ctx,"WARP device through proxy");return d;}
ComPtr<ID3D11Texture2D> texture(ID3D11Device*d,unsigned w,unsigned h,unsigned salt){std::vector<unsigned char> px(size_t(w)*h*4);for(unsigned y=0;y<h;++y)for(unsigned x=0;x<w;++x){auto i=(y*w+x)*4;px[i]=(x*37+y*11+salt*17)&255;px[i+1]=static_cast<unsigned char>((x<w/2?48:192)+((y*3+salt)&31));px[i+2]=(y*53+x*7+salt*29)&255;px[i+3]=255;}D3D11_TEXTURE2D_DESC td{};td.Width=w;td.Height=h;td.MipLevels=td.ArraySize=td.SampleDesc.Count=1;td.Format=DXGI_FORMAT_R8G8B8A8_UNORM;td.BindFlags=D3D11_BIND_SHADER_RESOURCE|D3D11_BIND_UNORDERED_ACCESS;D3D11_SUBRESOURCE_DATA sd{px.data(),w*4,0};ComPtr<ID3D11Texture2D>o;require(SUCCEEDED(d->CreateTexture2D(&td,&sd,&o)),"source texture");return o;}
std::vector<unsigned char> pixels(ID3D11Device*d,ID3D11DeviceContext*c,ID3D11Texture2D*i){D3D11_TEXTURE2D_DESC td{};i->GetDesc(&td);require(td.Format==DXGI_FORMAT_R8G8B8A8_UNORM,"RGBA8 output");td.Usage=D3D11_USAGE_STAGING;td.BindFlags=0;td.CPUAccessFlags=D3D11_CPU_ACCESS_READ;ComPtr<ID3D11Texture2D>s;require(SUCCEEDED(d->CreateTexture2D(&td,nullptr,&s)),"staging");c->CopyResource(s.Get(),i);D3D11_MAPPED_SUBRESOURCE m{};require(SUCCEEDED(c->Map(s.Get(),0,D3D11_MAP_READ,0,&m)),"map staging");std::vector<unsigned char>o(size_t(td.Width)*td.Height*4);for(UINT y=0;y<td.Height;++y)std::memcpy(o.data()+size_t(y)*td.Width*4,static_cast<const unsigned char*>(m.pData)+size_t(y)*m.RowPitch,td.Width*4);c->Unmap(s.Get(),0);return o;}
std::vector<unsigned char> crop(const std::vector<unsigned char>& p,unsigned w,unsigned h,unsigned x0,unsigned x1){std::vector<unsigned char>o(size_t(x1-x0)*h*4);for(unsigned y=0;y<h;++y)std::memcpy(o.data()+size_t(y)*(x1-x0)*4,p.data()+size_t(y)*w*4+x0*4,(x1-x0)*4);return o;}
void bindings(ID3D11DeviceContext*c,ID3D11ShaderResourceView*s,ID3D11UnorderedAccessView*u,ID3D11Buffer*b){ComPtr<ID3D11ShaderResourceView>gs;ComPtr<ID3D11UnorderedAccessView>gu;ComPtr<ID3D11Buffer>gb;c->CSGetShaderResources(0,1,&gs);c->CSGetUnorderedAccessViews(0,1,&gu);c->CSGetConstantBuffers(0,1,&gb);require(gs.Get()==s&&gu.Get()==u&&gb.Get()==b,"producer CS bindings preserved");}
void run(const wchar_t*path,bool on){Watchdog wd;Device d=open(path);auto direct=reinterpret_cast<DirectSharpen>(GetProcAddress(d.module,"edvrSharpen"));require(direct!=nullptr,"direct sharpen export");NativeSharpenClient client;require(client.acquire(d.module,d.dev.Get(),41)==S_OK,"sharpen acquire");auto src=texture(d.dev.Get(),640,128,3);auto before=pixels(d.dev.Get(),d.ctx.Get(),src.Get());auto sentinelSrvTex=texture(d.dev.Get(),8,8,71);auto sentinelUavTex=texture(d.dev.Get(),8,8,83);ComPtr<ID3D11ShaderResourceView>srv;ComPtr<ID3D11UnorderedAccessView>uav;ComPtr<ID3D11Buffer>cb;require(SUCCEEDED(d.dev->CreateShaderResourceView(sentinelSrvTex.Get(),nullptr,&srv)),"SRV");require(SUCCEEDED(d.dev->CreateUnorderedAccessView(sentinelUavTex.Get(),nullptr,&uav)),"UAV");D3D11_BUFFER_DESC bd{};bd.ByteWidth=16;bd.BindFlags=D3D11_BIND_CONSTANT_BUFFER;require(SUCCEEDED(d.dev->CreateBuffer(&bd,nullptr,&cb)),"constant buffer");d.ctx->CSSetShaderResources(0,1,srv.GetAddressOf());d.ctx->CSSetUnorderedAccessViews(0,1,uav.GetAddressOf(),nullptr);d.ctx->CSSetConstantBuffers(0,1,cb.GetAddressOf());bindings(d.ctx.Get(),srv.Get(),uav.Get(),cb.Get());const vr::VRTextureBounds_t left{0,0,.5f,1};const vr::VRTextureBounds_t right{1,1,.5f,0};ComPtr<ID3D11Texture2D>out;vr::VRTextureBounds_t ob{};auto hr=client.treat(1,0,src.Get(),&left,out,ob);if(!on){require(hr==S_FALSE&&!out&&!ob.uMin&&!ob.uMax&&!ob.vMin&&!ob.vMax,"off mode refuses");require(pixels(d.dev.Get(),d.ctx.Get(),src.Get())==before,"off leaves source");ComPtr<ID3D11Texture2D>offRight;require(client.treat(1,1,src.Get(),&right,offRight,ob)==S_FALSE&&!offRight,"off mode refuses both eyes");require(client.close()==S_OK,"off close");return;}require(hr==S_OK&&out,"left output");D3D11_TEXTURE2D_DESC od{};out->GetDesc(&od);require(od.Width==320&&od.Height==128,"left region size");require(ob.uMin==0&&ob.vMin==0&&ob.uMax==1&&ob.vMax==1,"left output bounds");bindings(d.ctx.Get(),srv.Get(),uav.Get(),cb.Get());auto leftPx=pixels(d.dev.Get(),d.ctx.Get(),out.Get());require(leftPx!=crop(before,640,128,0,320),"sharpening changes cropped pixels");require(pixels(d.dev.Get(),d.ctx.Get(),src.Get())==before,"source unchanged");float lb[4]={0,0,.5f,1};auto raw=reinterpret_cast<ID3D11Texture2D*>(direct(src.Get(),0,lb,.7f));require(raw,"direct left reference");raw->AddRef();ComPtr<ID3D11Texture2D>ref;ref.Attach(raw);require(pixels(d.dev.Get(),d.ctx.Get(),ref.Get())==leftPx,"native left matches direct reference");ComPtr<ID3D11Texture2D>rightOut;hr=client.treat(1,1,src.Get(),&right,rightOut,ob);require(hr==S_OK&&rightOut,"right output");rightOut->GetDesc(&od);require(od.Width==320&&od.Height==128&&ob.uMin==1&&ob.vMin==1&&ob.uMax==0&&ob.vMax==0,"flipped right bounds");bindings(d.ctx.Get(),srv.Get(),uav.Get(),cb.Get());auto rightPx=pixels(d.dev.Get(),d.ctx.Get(),rightOut.Get());require(rightOut.Get()!=out.Get()&&rightPx!=leftPx,"eyes independent");float rb[4]={1,1,.5f,0};auto rawRight=reinterpret_cast<ID3D11Texture2D*>(direct(src.Get(),1,rb,.7f));require(rawRight,"direct right reference");rawRight->AddRef();ComPtr<ID3D11Texture2D>rightRef;rightRef.Attach(rawRight);require(pixels(d.dev.Get(),d.ctx.Get(),rightRef.Get())==rightPx,"native right matches direct reference");require(client.invalidate()==S_OK,"invalidate");ComPtr<ID3D11Texture2D>refused;require(client.treat(1,0,src.Get(),&left,refused,ob)!=S_OK&&!refused,"invalidated sequence refused");src=texture(d.dev.Get(),800,160,9);before=pixels(d.dev.Get(),d.ctx.Get(),src.Get());require(client.treat(2,0,src.Get(),&left,out,ob)==S_OK&&out,"resize output");out->GetDesc(&od);require(od.Width==400&&od.Height==160,"resize dimensions");require(pixels(d.dev.Get(),d.ctx.Get(),src.Get())==before,"resized source unchanged");HRESULT closed=E_FAIL;std::thread closer([&]{closed=client.close();});closer.join();require(closed==S_OK,"CPU close");ComPtr<ID3D11Texture2D>stale;require(client.treat(3,0,src.Get(),&left,stale,ob)!=S_OK&&!stale,"close refuses stale treat");d.ctx->ClearState();d.ctx->Flush();}
}
int wmain(int argc,wchar_t**argv){SetErrorMode(SEM_FAILCRITICALERRORS|SEM_NOGPFAULTERRORBOX|SEM_NOOPENFILEERRORBOX);if(argc==2&&!wcscmp(argv[1],L"--dry-run")){std::puts("native_sharpen_gpu_test: dry-run (no DLL, device or files)");return 0;}if(argc!=4||wcscmp(argv[1],L"--self-test")||(wcscmp(argv[3],L"on")&&wcscmp(argv[3],L"off")))return 2;try{run(argv[2],!wcscmp(argv[3],L"on"));std::printf("native_sharpen_gpu_test: mode=%ls, %u checks, 0 failures\n",argv[3],checks);return 0;}catch(const std::exception&e){std::printf("native_sharpen_gpu_test: FAIL: %s\n",e.what());return 1;}}
